1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isNeighbourOf = (cell: Cell, candidate: Cell): boolean =>
7	  !isSameCell(cell, candidate) &&
8	  Math.abs(candidate[0] - cell[0]) <= 1 &&
9	  Math.abs(candidate[1] - cell[1]) <= 1;
10	
11	const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
12	  liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
13	
14	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
15	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
16	
17	const NEIGHBOURS_TO_SURVIVE = [2, 3];
18	const NEIGHBOURS_TO_BE_BORN = [3];
19	
20	const isAliveNextGeneration = (cell: Cell, liveCells: Cell[]): boolean => {
21	  const neighbours = countLiveNeighbours(cell, liveCells);
22	  const neighbourCountsForLife = isAlive(cell, liveCells)
23	    ? NEIGHBOURS_TO_SURVIVE
24	    : NEIGHBOURS_TO_BE_BORN;
25	
26	  return neighbourCountsForLife.includes(neighbours);
27	};
28	
29	const NEIGHBOUR_OFFSETS = [-1, 0, 1];
30	
31	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
32	
33	const cellAndItsNeighbours = ([x, y]: Cell): Cell[] =>
34	  NEIGHBOUR_OFFSETS.flatMap((offsetX) =>
35	    NEIGHBOUR_OFFSETS.map((offsetY): Cell => [x + offsetX, y + offsetY]),
36	  );
37	
38	const deduplicated = (cells: Cell[]): Cell[] => [
39	  ...new Map(cells.map((cell) => [cellKey(cell), cell])).values(),
40	];
41	
42	const cellsToEvaluate = (liveCells: Cell[]): Cell[] =>
43	  deduplicated(liveCells.flatMap(cellAndItsNeighbours));
44	
45	export function nextGeneration(liveCells: Cell[]): Cell[] {
46	  return cellsToEvaluate(liveCells).filter((cell) =>
47	    isAliveNextGeneration(cell, liveCells),
48	  );
49	}
